import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.bIR-4glx.js";const f=JSON.parse('{"title":"Book Roadmap","description":"A six-part map of Still Here, three reading paths through it, and a way to begin when you have five minutes or very little capacity today.","frontmatter":{"title":"Book Roadmap","description":"A six-part map of Still Here, three reading paths through it, and a way to begin when you have five minutes or very little capacity today.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-0/roadmap.md","filePath":"en/threads/part-0/roadmap.md","lastUpdated":1795392000000}'),i={name:"en/threads/part-0/roadmap.md"};function n(d,e,h,s,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="book-roadmap" tabindex="-1">Book Roadmap <a class="header-anchor" href="#book-roadmap" aria-label="Permalink to &quot;Book Roadmap&quot;">​</a></h1><p>This book begins with one ordinary person&#39;s failure and recovery, then moves into relearning, working with AI, daily practice, and long-term action. You do not have to read it in order, but it helps to see the whole map first.</p><h2 id="the-shape-of-the-book" tabindex="-1">The Shape of the Book <a class="header-anchor" href="#the-shape-of-the-book" aria-label="Permalink to &quot;The Shape of the Book&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>The question it asks</th><th>Start here</th></tr></thead><tbody><tr><td>Prologue and opening</td><td>Why would I begin again? What is this book offering?</td><td><a href="./prologue">Prologue</a> · <a href="./reader-guide">How to Read This Book</a></td></tr><tr><td>Part I: Return to Life</td><td>When failure, the body, relationships, and work fall out of order, how do I catch myself first?</td><td><a href="./../part-2/return-to-life">Part I Introduction</a> · <a href="./../part-2/my-story">My Story</a></td></tr><tr><td>Part II: Learning Again, Opening Input</td><td>After recovery, how do I retrain attention and ability through one concrete task?</td><td><a href="./../part-1/open-input">Part II Introduction</a> · <a href="./../part-1/0-cefr">CEFR Self-check</a></td></tr><tr><td>Part III: Amplify Ability</td><td>How do I use AI without handing over judgment, privacy, and responsibility?</td><td><a href="./../part-3/amplify-ability">Part III Introduction</a> · <a href="./../part-3/1-ai-learning">Learning Anything with AI</a></td></tr><tr><td>Part IV: Practice and Recovery</td><td>How do learning, the body, family, and ordinary days fit together, and how do I return after interruption?</td><td><a href="./../part-4/practice-and-recovery">Part IV Introduction</a> · <a href="./../part-4/week-1">First Week Practice</a></td></tr><tr><td>Part V: Long-Term Action</td><td>How does one round of practice become real work that still echoes after ninety days?</td><td><a href="./../part-5/long-term-action">Part V Introduction</a> · <a href="./../part-5/90-day-plan">90-Day Action Plan</a></td></tr><tr><td>Part VI: Be Your Own Lifelong Friend</td><td>How do I understand, care for, improve, and live with myself over time?</td><td><a href="./../part-6/1-understanding-yourself">Understanding Yourself</a> · <a href="./../part-6/afterword">Afterword</a></td></tr></tbody></table><p>Directory names such as <code>part-2</code> and <code>part-1</code> are historical theme slugs, <strong>not reading order</strong>. The book&#39;s order is the one in this table and the table of contents: Part I (story and recovery) first, Part II (learning again) second.</p><h2 id="three-reading-paths" tabindex="-1">Three Reading Paths <a class="header-anchor" href="#three-reading-paths" aria-label="Permalink to &quot;Three Reading Paths&quot;">​</a></h2><h3 id="story-first" tabindex="-1">Story First <a class="header-anchor" href="#story-first" aria-label="Permalink to &quot;Story First&quot;">​</a></h3><p>For a reader who wants to be understood before being taught.</p><ol><li><a href="./prologue">Prologue</a> → <a href="./../part-2/my-story">My Story</a>;</li><li><a href="./../part-2/depression-anxiety-recovery">I Am Still Here</a> → <a href="./../part-2/recovery">Recovery</a>;</li><li><a href="./../part-2/decision">Decision-Making</a> → <a href="./../part-2/relationships">Relationships</a>;</li><li>When you have room, enter the <a href="./../part-1/open-input">Part II Introduction</a>.</li></ol><h3 id="method-first" tabindex="-1">Method First <a class="header-anchor" href="#method-first" aria-label="Permalink to &quot;Method First&quot;">​</a></h3><p>For a reader who arrives with one concrete task and wants to start quickly.</p><ol><li><a href="./../part-1/0-cefr">CEFR Self-check</a> → <a href="./../part-1/1-understanding">Learning Principles</a>;</li><li>Choose <strong>one</strong> line among vocabulary, grammar, listening, reading, speaking, and writing, and finish one fourteen-day experiment;</li><li><a href="./../part-3/1-ai-learning">Learning Anything with AI</a> → <a href="./../part-3/4-artifacts-and-delivery">Artifacts</a>;</li><li><a href="./../part-4/week-1">First Week Practice</a> → <a href="./../part-5/90-day-plan">90-Day Action Plan</a>.</li></ol><h3 id="when-capacity-is-small" tabindex="-1">When Capacity Is Small <a class="header-anchor" href="#when-capacity-is-small" aria-label="Permalink to &quot;When Capacity Is Small&quot;">​</a></h3><p>For a reader whose body or mood does not allow long reading today.</p><ol><li>Read only the “reduce the load” section of <a href="./../part-2/recovery">Recovery</a>, and do none of the exercises;</li><li>Open <a href="./../../templates/learning-state">Learning State</a> and write four lines: problem, clues, minimum action, boundary;</li><li>Stop there. Leave the <a href="./../../templates/rhythm-ledger">Rhythm Ledger</a> for tomorrow or next week. Do not do the homework later to catch up.</li></ol><p>You can switch paths midway. If a story makes you want to work, move to the method; if the method leaves you depleted, return to recovery. The structure allows travel in both directions.</p><h2 id="if-you-have-only-five-minutes-today" tabindex="-1">If You Have Only Five Minutes Today <a class="header-anchor" href="#if-you-have-only-five-minutes-today" aria-label="Permalink to &quot;If You Have Only Five Minutes Today&quot;">​</a></h2><p>If the only opening you have is very small, do not try to start a book:</p><ol><li>Open <a href="./../../templates/learning-state">Learning State</a>;</li><li>Write the one problem that is most real today;</li><li>Write one minimum action that can be finished <strong>today</strong>;</li><li>Write one boundary that must hold: privacy, body, relationships, or money.</li></ol><p>Those four lines are a beginning. Five minutes do not need to produce a conclusion. They only need to bring the next step out of the fog.</p><h2 id="after-you-finish" tabindex="-1">After You Finish <a class="header-anchor" href="#after-you-finish" aria-label="Permalink to &quot;After You Finish&quot;">​</a></h2><p>The appendices follow the main text and are organised by use: check the <a href="./../../reference/glossary">Glossary of Terms and Methods</a> first, then enter the <a href="./../../reference/reading-map">Reading Map</a> by problem; open the <a href="./../../templates/toolkit">Toolkit Overview</a> when you need to do something; consult the <a href="./../../reference/bibliography">Bibliography</a> and <a href="./../../reference/sources-and-citation">Sources, Citation, and Verification</a> when you want to cite or verify; read <a href="./../part-5/book-as-proof">the book case study</a> in the appendices if you want to know how this book itself was made.</p><p>If you finish, the trace worth keeping is not “I finished”. It is one real delivery, one retest record, or one decision you are willing to check again in ninety days. Put it in the <a href="./../../templates/90-day-cycle">90-Day Cycle Map</a>.</p>',23)])])}const y=t(i,[["render",n]]);export{f as __pageData,y as default};
